	// Find maximum matching
	matchPair := make([]int, pairCount) // matchPair[i] = domino index matched to pair i, or -1
	matchDomino := make([]int, len(dominos)) // matchDomino[j] = pair index matched to domino j, or -1
	for i := range matchPair {
