	dfs = func(u int, visited []bool) bool {
		for _, v := range pairToDomino[u] {
			if visited[v] {
				continue
			}
			visited[v] = true
			if matchDomino[v] == -1 || dfs(matchDomino[v], visited) {
				matchPair[u] = v
				matchDomino[v] = u
				return true
			}
		}
		return false
	}

	matchingSize := 0
	for i := 0; i < pairCount; i++ {
		visited := make([]bool, len(dominos))
		if dfs(i, visited) {
			matchingSize++
		}
	}

	// Answer: total shoes - 2 * matchingSize
	answer := n*m - 2*matchingSize
