	line, _ := reader.ReadString('\n')
	parts := strings.Fields(line)
	fmt.Sscanf(parts[0], "%d", &n)
	fmt.Sscanf(parts[1], "%d", &m)

	grid := make([][]int, n)
	positions := make(map[int][2]int)

	for i := 0; i < n; i++ {
		line, _ = reader.ReadString('\n')
		parts = strings.Fields(line)
		grid[i] = make([]int, m)
		for j := 0; j < m; j++ {
			fmt.Sscanf(parts[j], "%d", &grid[i][j])
			positions[grid[i][j]] = [2]int{i, j}
		}
	}

	// Count the number of pairs that are already adjacent
	adjacentPairs := 0
	visited := make(map[int]bool)

	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			val := grid[i][j]
			if visited[val] {
				continue
			}
			// Find the other shoe of this pair
			// We need to find where the other shoe is
			// positions[val] gives one position, but we need both
			// Let's find both positions
			pos1 := [2]int{-1, -1}
			pos2 := [2]int{-1, -1}
			found := 0
			for r := 0; r < n; r++ {
				for c := 0; c < m; c++ {
					if grid[r][c] == val {
						if found == 0 {
							pos1 = [2]int{r, c}
						} else {
							pos2 = [2]int{r, c}
						}
						found++
					}
				}
			}
			visited[val] = true

			// Check if they are adjacent
			dist := abs(pos1[0]-pos2[0]) + abs(pos1[1]-pos2[1])
			if dist == 1 {
				adjacentPairs++
			}
		}
	}

	totalPairs := n * m / 2
	// Each pair that is not adjacent needs at least 1 shoe to be moved
	// Actually, if a pair is not adjacent, we need to move at least one shoe
	// The minimum number of shoes to move is the number of pairs that are NOT adjacent
	// Because for each non-adjacent pair, we can move one shoe to be next to the other
	// And this is achievable simultaneously for all pairs

	minShoesToMove := totalPairs - adjacentPairs

	fmt.Fprintf(writer, "%d\n", minShoesToMove)
